@page "/notifications"
@rendermode InteractiveServer
@using sv_6dc91b54a35740f8b63fd41f4fa91027.Services
@inject INotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@(Notifications?.Count ?? 0)</span></h1>

@if (Notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (Notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not already restored from prerender state
        Notifications ??= await NotificationService.GetNotificationsAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // OnAfterRender never runs during prerender — safe to start polling here
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                var lastId = Notifications?.Max(n => n.Id) ?? 0;
                var newNotifications = await NotificationService.GetNewNotificationsSinceAsync(lastId);

                if (newNotifications.Count > 0)
                {
                    Notifications ??= [];
                    Notifications.AddRange(newNotifications);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

