+{
+    private int _nextId = 4;
+    private readonly List<Notification> _notifications =
+    [
+        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
+        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
+        new() { Id = 3, Message = "New feature available: Dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
+    ];
+
+    private readonly string[] _fakeMessages =
+    [
+        "You have a new follower.",
+        "Your report is ready to download.",
+        "Scheduled maintenance tonight at 11 PM.",
+        "Someone commented on your post.",
+        "Your subscription renews tomorrow.",
+    ];
+
+    public Task<List<Notification>> GetNotificationsAsync()
+    {
+        return Task.FromResult(_notifications.ToList());
+    }
+
+    public Task<List<Notification>> GetNewNotificationsSinceAsync(int lastId)
+    {
+        // Simulate ~30% chance of a new notification each poll
+        if (Random.Shared.Next(0, 3) == 0)
+        {
+            var msg = _fakeMessages[Random.Shared.Next(_fakeMessages.Length)];
+            _notifications.Add(new Notification
+            {
+                Id = _nextId++,
+                Message = msg,
+                Timestamp = DateTime.UtcNow,
+            });
+        }
+
+        var newOnes = _notifications.Where(n => n.Id > lastId).ToList();
+        return Task.FromResult(newOnes);
+    }
+}
+

